+// API keys and roles. Keys live in `store.data.apiKeys` as { key, name, role }.
+// Roles are ordered: viewer < cook < manager; a role may do what the roles
+// below it may do.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a bearer `key`; throws `unauthorized` if there is none. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || key === "") throw new AppError("unauthorized");
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), wanted) && !found) found = k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Whether `role` may do what `needed` may do. */
+export function roleAllows(role, needed) {
+  const have = ROLES.indexOf(role);
+  return have >= 0 && have >= ROLES.indexOf(needed);
+}
+
+/** Throws `forbidden` unless `role` may do what `needed` may do. */
+export function requireRole(role, needed) {
+  if (!roleAllows(role, needed)) throw new AppError("forbidden", { role, needed });
+}
