+// The audit log: one entry per request that changes data. Entries are only
+// appended, never edited or deleted.
+
+/** Appends an audit entry { id, at, keyName, method, path, status } and returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName: keyName ?? null, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => (a.at < b.at ? 1 : a.at > b.at ? -1 : b.id - a.id));
+}
