+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth, KEYS } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  const b = await raw({ path: "/items", headers: auth("nope") });
+  assert.equal(b.status, 401);
+  const c = await raw({ path: "/items", headers: { authorization: KEYS.manager } });
+  assert.equal(c.status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { raw, store } = app();
+  assert.equal((await raw({ path: "/items", headers: auth(KEYS.viewer) })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await raw({ method: "POST", path: "/recipes/1/cook", headers: auth(KEYS.viewer), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, but not more", async () => {
+  const { raw, handle } = app();
+  const as = (method, path, body) => raw({ method, path, body, headers: auth(KEYS.cook) });
+  assert.equal((await as("POST", "/recipes/1/cook", { portions: 1 })).status, 200);
+  assert.equal((await as("POST", "/batches/1/waste", { qty: 1, reason: "dropped" })).status, 201);
+  assert.equal((await as("POST", "/temperatures", { location: "fridge", celsius: 3 })).status, 201);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await as("POST", `/stocktakes/${take.id}/counts`, { batchId: 6, counted: 12 })).status, 200);
+  assert.equal((await as("POST", `/stocktakes/${take.id}/finish`)).status, 403);
+  assert.equal((await as("POST", "/stocktakes", { location: "fridge" })).status, 403);
+  assert.equal((await as("POST", "/orders", { supplierId: 1, lines: [] })).status, 403);
+  assert.equal((await as("GET", "/audit")).status, 403);
+});
+
+test("changes are audited, newest first, for managers only", async () => {
+  const { raw, handle } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: auth(KEYS.viewer), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: auth(KEYS.cook), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/jobs/nightly" });
+  await handle({ path: "/items" });
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })), [
+    { keyName: null, method: "POST", path: "/jobs/nightly", status: 401 },
+    { keyName: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    { keyName: "front of house", method: "POST", path: "/recipes/1/cook", status: 403 },
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.equal((await raw({ path: "/audit", headers: auth(KEYS.viewer) })).status, 403);
+});
